<?php require_once 'includes/admin_common.php'; header('Content-Type: application/json'); function out($s,$m){echo json_encode(['success'=>$s,'message'=>$m]);exit;} verify_csrf(); $id=(int)($_POST['id']??0);$action=$_POST['action']??''; if($id<1) out(false,'Invalid user.'); $u=fetch_one('SELECT * FROM ustads WHERE id=?','i',[$id]); if(!$u) out(false,'User not found.'); switch($action){case 'unlock': execute_stmt('UPDATE ustads SET lock_until=NULL WHERE id=?','i',[$id]); out(true,'Account unlocked.'); case 'reset_failed': execute_stmt('UPDATE ustads SET failed_attempts=0,lock_until=NULL WHERE id=?','i',[$id]); out(true,'Failed attempts reset.'); case 'logout': execute_stmt('UPDATE ustads SET is_logged_in=0,remember_token=NULL WHERE id=?','i',[$id]); out(true,'User logged out.'); case 'reset_password': $p=(string)($_POST['password']??bin2hex(random_bytes(6))); if(strlen($p)<8) out(false,'Password must be at least 8 characters.'); $h=password_hash($p,PASSWORD_DEFAULT); execute_stmt('UPDATE ustads SET password=?,reset_token=NULL,reset_expires=NULL,reset_verified=0 WHERE id=?','si',[$h,$id]); out(true,'Password reset successfully.'); case 'enable_login': execute_stmt('UPDATE ustads SET lock_until=NULL,email_locked=0 WHERE id=?','i',[$id]); out(true,'Login enabled.'); case 'disable_login': execute_stmt("UPDATE ustads SET lock_until=DATE_ADD(NOW(), INTERVAL 100 YEAR) WHERE id=?",'i',[$id]); out(true,'Login disabled.'); default: out(false,'Unknown action.'); }
